import sys
lines = sys.stdin.read().split()
if len(lines) >= 2:
    s, t = lines[0], lines[1]
    m, n = len(s), len(t)
    dp = [0] * (n + 1)
    dp[0] = 1
    for char_s in s:
        for j in range(n, 0, -1):
            if char_s == t[j-1]:
                dp[j] += dp[j-1]
    print(dp[n])
else:
    print(0)
